package com.spai.portal.integration.controller;
import java.io.InputStream;import java.util.*;import com.fasterxml.jackson.databind.*;import com.spai.portal.common.ApiResponse;import com.spai.portal.integration.domain.SyncJob;import com.spai.portal.integration.repository.SyncJobRepository;import com.spai.portal.task.domain.DeliveryTask;import com.spai.portal.task.repository.DeliveryTaskRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/admin/imports")@PreAuthorize("hasRole('ADMIN')")public class ImportController{private final ObjectMapper json;private final DeliveryTaskRepository tasks;private final SyncJobRepository jobs;public ImportController(ObjectMapper json,DeliveryTaskRepository tasks,SyncJobRepository jobs){this.json=json;this.tasks=tasks;this.jobs=jobs;}@PostMapping("/tasks-json")@Transactional public ApiResponse<SyncJob>tasks(@RequestParam("file")MultipartFile file)throws Exception{SyncJob job=start("TASK_JSON");int total=0,success=0,errors=0;try(InputStream in=file.getInputStream()){JsonNode root=json.readTree(in);if(!root.isArray())throw new IllegalArgumentException("任务文件必须是 JSON 数组");for(JsonNode n:root){total++;try{String external=n.path("id").asText();if(external.isEmpty())throw new IllegalArgumentException("缺少 id");DeliveryTask t=tasks.findByExternalId(external).orElseGet(()->{DeliveryTask value=new DeliveryTask();value.setId(UUID.randomUUID().toString());return value;});t.setExternalId(external);t.setStage(n.path("stage").asText());t.setScene(n.path("scene").asText());t.setAi(n.path("ai").asText());t.setDescription(n.path("desc").asText());t.setInput(n.path("input").asText());t.setOutput(n.path("output").asText());t.setType(n.path("type").asText());t.setSkill(n.path("skill").asText());t.setPriority(n.path("pri").asText());t.setDifficulty(n.path("diff").asText());tasks.save(t);success++;}catch(RuntimeException e){errors++;}}}job.setTotalCount(total);job.setSuccessCount(success);job.setErrorCount(errors);job.setStatus(errors==0?"SUCCESS":"PARTIAL_SUCCESS");job.setFinishedAt(java.time.OffsetDateTime.now());return ApiResponse.ok(jobs.save(job));}private SyncJob start(String source){SyncJob j=new SyncJob();j.setId(UUID.randomUUID().toString());j.setSource(source);j.setStatus("RUNNING");return jobs.save(j);}}
